# The reference-model refit was already replaced above. Do not patch it twice.

def _unified_exec(source, module_name="__main__"):
    """Execute an embedded source as a real registered module.

    Registering the temporary module in sys.modules is required on Python 3.13
    for dataclasses defined inside embedded sources. Without registration,
    dataclasses can fail while resolving cls.__module__.
    """
    import types as _unified_types

    _module = _unified_types.ModuleType(module_name)
    _module.__file__ = str(_UnifiedPath(__file__).resolve())
    _module.__package__ = None
    _unified_sys.modules[module_name] = _module

    try:
        exec(
            compile(source, _module.__file__, "exec"),
            _module.__dict__,
            _module.__dict__,
        )
        return _module.__dict__
    except Exception:
        # Leave the module registered during execution so dataclasses and
        # related introspection work correctly, but clean up a failed temporary
        # library module before re-raising.
        if module_name != "__main__":
            _unified_sys.modules.pop(module_name, None)
        raise


def _cleanup_legacy_figure_directories():
    """Remove pre-unification robustness figure folders if they exist."""
    _root = _UnifiedPath(__file__).resolve().parent
    for _name in (
        "Bet_Hedging_Robustness_Audit_Sup_Figures",
        "Chapter7_Every7_BetHedging_Robustness_Audit_Figures",
    ):
        _p = _root / _name
        if _p.exists():
            _unified_shutil.rmtree(_p, ignore_errors=True)


def _run_figures_7_5_to_7_8_only():
    """Generate only the four late Chapter 7 thesis figures.

    Figures 7.5-7.7 use the already-defined primary-model calculations.
    Figure 7.8 uses the already-defined five-day counterfactual helper from the
    robustness source, without running the full robustness audit.
    """
    _cleanup_legacy_figure_directories()

    # Load the primary model as a library, fit/reuse its cached final model, and
    # generate only Figures 7.5-7.7.
    _PNS = _unified_exec(_PRIMARY_SOURCE, module_name="_primary_figure_library")
    _OBS, _SEM, _N, _tidy = _PNS["load_data"]()
    _fit_key = _PNS["_cache_key"](
        "primary_fit", _OBS, _SEM,
        _PNS["MU_W"], _PNS["MU_E"], _PNS["MU_CDEII"],
        _PNS["MU_HEAT_MULTIPLIER"], _PNS["GEN_PER_DAY"], _PNS["PRE_GEN"],
    )
    _cached = _PNS["_cache_load_pickle"]("primary_fit", _fit_key)
    if _cached is None:
        _best = _PNS["fit"](_OBS, _SEM, rate_model="shared")
        _P = _PNS["np"].asarray(_best.x, float)
        _PNS["_cache_save_pickle"](
            "primary_fit", _fit_key,
            {"x": _P, "cost": float(_best.cost)},
        )
    else:
        _P = _PNS["np"].asarray(_cached["x"], float)

    _PNS["fig7_17_geometric_mean_rate_sweep"](
        _P,
        path="Figure_7.5_Environmental_Switching_Frequency_Defines_the_Conditions_Under_Which_Elevated_Chromosome_Instability_Is_Advantageous.png",
    )
    _PNS["make_refined_schematic_02a_variants"](_P)
    _PNS["fig7_4xxv_relationship_landscape_pair"](
        _P,
        path="Figure_7.7_Pre-Heat_Chromosome-State_Separation_Predicts_the_Environmental_Window_of_Edited-Strain_Persistence.png",
    )

    # Load the robustness code as a library ONLY. Its main() is not called.
    # This therefore generates Figure 7.8 without the full audit or its legacy
    # figure-output folders.
    _ANS = _unified_exec(_ROBUSTNESS_AUDIT_SOURCE, module_name="_figure_7_8_library")
    _ANS["_figure_7_8_three_panel_variant"](
        p=_ANS["P"],
        mu_e=_ANS["MU_E"],
        period=5,
        diff_style="halo_dashed",
    )

    _cleanup_legacy_figure_directories()

    _fig_dir = _UnifiedPath(__file__).resolve().parent / (
        f"{_UnifiedPath(__file__).stem} Figures"
    )
    _expected = [
        "Figure_7.5_Environmental_Switching_Frequency_Defines_the_Conditions_Under_Which_Elevated_Chromosome_Instability_Is_Advantageous.png",
        "Figure_7.6_Model-Predicted_Recurrent_Pre-Heat_Chromosome-State_Fractions.png",
        "Figure_7.7_Pre-Heat_Chromosome-State_Separation_Predicts_the_Environmental_Window_of_Edited-Strain_Persistence.png",
        "Figure_7.8_Five-Day_Counterfactual_Removal_of_Pre-Heat_Differential_Retention.png",
    ]
    _missing = [_name for _name in _expected if not (_fig_dir / _name).exists()]
    if _missing:
        raise RuntimeError(
            "Late Chapter 7 figure generation finished but these files are missing: "
            + ", ".join(_missing)
        )

    print("\nCURRENT THESIS FIGURES 7.5-7.8 WRITTEN TO:")
    print(_fig_dir)
    for _name in _expected:
        print("  ", _name)


def _refresh_comparison_exports_from_existing_tables(_PNS, _P):
    """Reconcile saved exports WITHOUT optimising any alternative model.

    Existing alternative-fit results are preserved. Table 7.5 is explicitly
    an approximate, non-nested sensitivity formulation, not a likelihood-ratio
    test of a strict extension of the primary model.
    """
    import numpy as np
    import pandas as pd
    root = _PNS["ADDITIONAL_FILES_DIR"]
    needed = [
        "Table_7.3_priming_comparison.csv",
        "Table_7.3b_mechanistic_ablation_ladder.csv",
        "Table_7.4_rate_formulation_comparison.csv",
        "Table_7.5_generations_per_day_comparison.csv",
    ]
    absent = [n for n in needed if not (root / n).is_file()]
    if absent:
        print("COMPARISON EXPORTS NOT REFRESHED: missing " + ", ".join(absent))
        print("  Existing comparison files are untouched. No refitting performed.")
        return

    obs, sem, _, _ = _PNS["load_data"]()
    g = _PNS["gof"](_P, obs, 8, rate_model="shared")
    vals = {
        "RSS": float(g["rss"]), "R2": float(g["R2"]),
        "RMSE": float(np.sqrt(g["rss"] / g["n"])),
        "AIC": float(g["aic"]), "BIC": float(g["bic"]),
    }
    src = [pd.read_csv(root / n) for n in needed]
    # No alternate-model fitted statistics are fabricated or overwritten.
    identifiers = [
        ("model", "With priming (final model)"),
        ("model", "Full model"),
        ("formulation", "Shared 11.5-fold heat multiplier (final model)"),
        ("model", "Fixed 10 generations/day"),
    ]
    for df, (field, label) in zip(src, identifiers):
        matches = df[field].eq(label)
        if int(matches.sum()) != 1:
            raise RuntimeError(f"Cannot reconcile comparison: expected exactly one {label!r}")
        for col, value in vals.items():
            name = col.lower() if label == "Full model" and col in ("RSS", "AIC", "BIC") else col
            if name not in df.columns:
                raise RuntimeError(f"Missing column {name} in comparison table {label}")
            df.loc[matches, name] = value
        # Recalculate information-criterion differences within each table.
        if "delta_AIC" in df:
            ac = "aic" if "aic" in df else "AIC"
            df["delta_AIC"] = df[ac] - df[ac].min()
        if "delta_BIC" in df:
            bc = "bic" if "bic" in df else "BIC"
            df["delta_BIC"] = df[bc] - df[bc].min()
    # Preserve the alternative rows of Table 7.5 but flag their limitations.
    _table75_exact = ("simulation_method" in src[3].columns and
                      src[3]["simulation_method"].eq("exact_matrix_power_v2").all())
    src[3]["interpretation_note"] = np.where(
        src[3]["model"].eq("Fixed 10 generations/day"),
        "Primary exact 10-generation model; shared fitted parameters",
        ("Exact matrix-power generation simulator; baseline identity verified"
         if _table75_exact else
         "Legacy approximate variable-generation simulator; rerun Table 7.5 before interpreting")
    )
    exports=[]
    for df, label in zip(src, (
        "stress priming", "mechanistic architecture",
        "transition-rate formulation", "generations per day")):
        piece=df.rename(columns={"model": "formulation", "rss": "RSS", "aic": "AIC", "bic": "BIC"}).copy()
        piece.insert(0, "comparison", label)
        exports.append(piece)
    summary = pd.concat(exports, ignore_index=True, sort=False)
    # Construct all outputs before writing, and use atomic replacement.
    import os
    for fname, frame in list(zip(needed, src)) + [("model_comparison_summary.csv", summary)]:
        dst = root / fname
        tmp = root / (fname + ".tmp")
        frame.to_csv(tmp, index=False, float_format="%.17g")
        os.replace(tmp, dst)
    print("COMPARISON CSVs REFRESHED FROM EXISTING TABLES; NO ALTERNATIVE REFITS")
    print("  Primary reference: R2={:.6f}, RMSE={:.6f}, AIC={:.3f}".format(
        vals["R2"], vals["RMSE"], vals["AIC"]))
    print("  Table 7.5: " + ("exact matrix-power alternatives" if _table75_exact else "legacy approximate alternatives — not validated"))
    check = pd.read_csv(root / "model_comparison_summary.csv")
    mainrows = check[check["formulation"].isin([v for _, v in identifiers])]
    if len(mainrows) != 4 or not np.allclose(mainrows["R2"].astype(float), vals["R2"], atol=1e-12):
        raise RuntimeError("Saved summary reference rows did not pass verification")
    print("SAVED COMPARISON REFERENCE CHECK: PASS")


def _run_complete_thesis_workflow():
    """One-click repository workflow: generate every current thesis figure.

    The primary embedded analysis produces the Chapter 5 figures, Chapter 7
    Figures 7.1-7.7, and Supplementary Figures 1-4.  The existing robustness
    helper is then loaded as a library only to generate current thesis Figure
    7.8.  No separate analysis modes or legacy figure directories are used.
    """
    _cleanup_legacy_figure_directories()

    print("\n" + "=" * 88)
    print("UNIFIED THESIS WORKFLOW: ALL CURRENT FIGURES")
    print("=" * 88)

    # Runs the complete current primary thesis workflow exactly once.
    _primary_ns = _unified_exec(_PRIMARY_SOURCE)

    # Export precisely the cached parameter vector that produced the figures.
    # No new fit is performed here.
    _PNS = _primary_ns
    _OBS, _SEM, _, _ = _PNS["load_data"]()
    _fit_key = _PNS["_cache_key"](
        "primary_fit", _OBS, _SEM, _PNS["MU_W"], _PNS["MU_E"],
        _PNS["MU_CDEII"], _PNS["MU_HEAT_MULTIPLIER"],
        _PNS["GEN_PER_DAY"], _PNS["PRE_GEN"]
    )
    _cached = _PNS["_cache_load_pickle"]("primary_fit", _fit_key)
    if _cached is None:
        raise RuntimeError("Primary fitted parameters were not saved to cache")
    _P = _PNS["np"].asarray(_cached["x"], float)
    _z = _PNS["compress_single"](_P)
    _param_path = _PNS["ADDITIONAL_FILES_DIR"] / "final_model_parameters.csv"
    _PNS["pd"].DataFrame({
        "parameter": _PNS["SINGLE_PNAMES"], "value": _z
    }).to_csv(_param_path, index=False, float_format="%.17g")
    print("SHARED FIT EXPORTED WITHOUT REFITTING:", _param_path)
    print("  w_WTan30 =", float(_z[0]))

    # Opt-in: recalculate ONLY Table 7.5 with the corrected simulator.
    # Leave the primary fit, other alternatives and all figures untouched.
    import os as _table75_os
    if _table75_os.environ.get("BET_HEDGING_TABLE75", "1") == "1":
        print("TABLE 7.5 ONLY: fitting two corrected generation-rate alternatives")
        _CNS = _unified_exec(_MODEL_COMPARISON_SOURCE, module_name="_table75_only_library")
        _CNS["compare_generation_formulations"](_OBS, _SEM, _P)
    _refresh_comparison_exports_from_existing_tables(_PNS, _P)

    # Generate only current thesis Figure 7.8 from the embedded robustness code.
    # Loading with a non-main module name prevents the robustness audit main()
    # from running and therefore prevents its historical extra output workflow.
    _audit_ns = _unified_exec(
        _ROBUSTNESS_AUDIT_SOURCE,
        module_name="_figure_7_8_library",
    )
    _audit_ns["_figure_7_8_three_panel_variant"](
        p=_audit_ns["P"],
        mu_e=_audit_ns["MU_E"],
        period=5,
        diff_style="halo_dashed",
    )

    _cleanup_legacy_figure_directories()

    _fig_dir = _UnifiedPath(__file__).resolve().parent / (
        f"{_UnifiedPath(__file__).stem} Figures"
    )
    _required_thesis = [
        'Figure_5.1_Agreement_Between_Reciprocal_kanMX_Marker_Orientations_in_Tube_and_Plate_Competitions.png',
        'Figure_5.2_Competition_Between_CEN3-Edited_Strains_and_CEN3-WT_Across_Five_Environmental_Regimes_in_5_mL_Cultures.png',
        'Figure_5.3_Calibration_of_Visual_G418-Resistance_Scores_Against_Known_Resistant-Cell_Proportions.png',
        'Figure_5.4_Competition_Between_CEN3-Edited_Strains_and_CEN3-WT_Across_Five_Environmental_Regimes_in_96-Well_Plates.png',
        'Figure_5.5_Divergence_of_Independent_Plate_Populations_Under_the_Intermediate_Switching_Regime.png',
        'Figure_5.6_Chromosome-Loss_Rate_Determines_the_Probability_of_Persistence_Under_the_Intermediate_Switching_Regime.png',
        'Figure_7.1_Four-State_Model_of_Competition_Between_CEN3-Edited_and_Wild-Type_Lineages.png',
        'Figure_7.2_The_Four-State_Model_Reproduces_Competition_Trajectories_Across_Five_Environmental_Regimes.png',
        'Figure_7.3_CEN3-cdeII_Delta_Competition_Dynamics_Predicted_by_the_Model_Fitted_to_CEN3-cdeI_II_Delta.png',
        'Figure_7.4_Environmental_Context_Determines_the_Competitive_Effect_of_Chromosome_III_Mis-Segregation_Rate.png',
        'Figure_7.5_Environmental_Switching_Frequency_Defines_the_Conditions_Under_Which_Elevated_Chromosome_Instability_Is_Advantageous.png',
        'Figure_7.6_Model-Predicted_Recurrent_Pre-Heat_Chromosome-State_Fractions.png',
        'Figure_7.7_Pre-Heat_Chromosome-State_Separation_Predicts_the_Environmental_Window_of_Edited-Strain_Persistence.png',
        'Figure_7.8_Five-Day_Counterfactual_Removal_of_Pre-Heat_Differential_Retention.png',
        'Supplementary_Figure_1_Recovery_of_the_Elevated_Chromosome_III_Heat_Advantage_Following_Growth_at_30C.png',
        'Supplementary_Figure_2_Profile-Likelihood_Analysis_of_the_Eight_Fitted_Model_Parameters.png',
        'Supplementary_Figure_3_Leave-One-Regime-Out_Prediction_Error_Across_Environmental_Schedules.png',
        'Supplementary_Figure_4_Representative_Competition_Trajectories_Across_Edited-Lineage_Mis-Segregation_Rates.png',
    ]
    _missing = [
        _name for _name in _required_thesis
        if not (_fig_dir / _name).exists()
    ]
    if _missing:
        raise RuntimeError(
            "Thesis workflow completed but these required thesis figures "
            "were not written: " + ", ".join(_missing)
        )

    print("\nALL CURRENT THESIS FIGURES COMPLETE.")
    print("Figure directory:", _fig_dir)

    # Alternative-model refits are valid biological comparisons but expensive.
    # Run explicitly with BET_HEDGING_COMPARISONS=1, never by default.
    import os as _workflow_os
    if _workflow_os.environ.get("BET_HEDGING_COMPARISONS", "0") == "1":
        print("\nFULL COMPARISON MODE: fitting alternative models only")
        _unified_exec(_MODEL_COMPARISON_SOURCE, module_name="__main__")
    else:
        print("FAST MODE: alternative-model comparisons not rerun; existing tables are unchanged.")
        print("The shared final_model_parameters.csv has been updated to match the figures.")


if __name__ != "__main__":
    exec(
        compile(_PRIMARY_SOURCE, str(_UnifiedPath(__file__).resolve()), "exec"),
        globals(),
        globals(),
    )
else:
    _run_complete_thesis_workflow()
